<template><main><NavBar/><section><h1>Support</h1><form @submit.prevent="create"><input v-model="subject" placeholder="Subject" required/><textarea v-model="body" placeholder="Describe the issue" required/><button>Open case</button></form><div class="layout"><aside><button v-for="item in cases" :key="item.id" @click="select(item)">{{item.subject}} · {{item.status}}</button></aside><article v-if="selected"><div v-for="message in messages" :key="message.id"><strong>@{{message.chatter_name}}</strong><p>{{message.body}}</p></div><form @submit.prevent="reply"><input v-model="replyBody" placeholder="Message"/><button>Send</button></form><button @click="closeCase">Close case</button></article></div></section></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import NavBar from'./NavBar.vue';import{addMessage,createCase,listCases,listMessages,setCaseStatus,type SupportCase,type SupportMessage}from'../api/support';const cases=ref<SupportCase[]>([]),selected=ref<SupportCase|null>(null),messages=ref<SupportMessage[]>([]),subject=ref(''),body=ref(''),replyBody=ref('');const load=async()=>cases.value=(await listCases()).cases;const select=async(item:SupportCase)=>{selected.value=item;messages.value=(await listMessages(item.id)).messages};const create=async()=>{await createCase(subject.value,body.value);subject.value='';body.value='';await load()};const reply=async()=>{if(!selected.value||!replyBody.value.trim())return;await addMessage(selected.value.id,replyBody.value);replyBody.value='';await select(selected.value)};const closeCase=async()=>{if(!selected.value)return;await setCaseStatus(selected.value.id,'closed');await load()};onMounted(load);</script>
<style scoped>main{min-height:100vh;background:var(--ink);padding:118px 20px 90px}section{max-width:960px;margin:auto}h1{font:700 3rem Georgia;margin:0 0 22px}section>form{padding:22px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}form{display:grid;gap:10px;margin:14px 0}input,textarea{padding:13px;border:1px solid var(--line);border-radius:10px;background:#111318;color:white}textarea{min-height:100px;resize:vertical}.layout{display:grid;grid-template-columns:260px 1fr;gap:18px;margin-top:22px}aside button{display:block;width:100%;margin:0 0 8px;text-align:left;background:var(--panel)}article{padding:20px;border:1px solid var(--line);border-radius:16px;background:var(--panel)}article>div{padding:10px 0;border-bottom:1px solid var(--line)}button{padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:var(--orange);color:white;cursor:pointer}@media(max-width:700px){.layout{display:block}aside{margin-bottom:18px}}</style>
